//! ⚖️ Standalone IFC2x3 STEP exchange graph admission; draft edits use their own domain rules.
use semio_s_artifact_stdio_ifc_2x3_base_model::standards::v2x3::subsets::base::schema::snapshot::Ifc2x3Snapshot;
use semio_s_artifact_stdio_contract::part21::Part21Value;
use std::collections::HashSet;
fn invalid(message:&str)->String{format!("ifc2x3: {message}")}
fn keyword(value:&str,checkpoint:&mut dyn FnMut(usize)->Result<(),String>)->Result<(),String>{if value.is_empty(){return Err(invalid("invalid STEP keyword"));}for(index,byte)in value.bytes().enumerate(){checkpoint(0)?;if !(byte.is_ascii_uppercase()||byte==b'_'||index>0&&byte.is_ascii_digit()){return Err(invalid("invalid STEP keyword"));}}Ok(())}
/// 🚦️ Validate borrowed graph/header structure with the original caller's per-value/depth observation.
pub fn validate_ifc2x3_exchange_with(snapshot:&Ifc2x3Snapshot,checkpoint:&mut dyn FnMut(usize)->Result<(),String>)->Result<(),String>{
 if snapshot.schema!="stdio.ifc.2x3"{return Err(invalid("unsupported snapshot schema"));}
 if let Some(preamble)=&snapshot.edm_preamble{for value in [preamble.producer.as_str(),preamble.module.as_str(),preamble.creation_date.as_str(),preamble.host.as_str(),preamble.database.as_str(),preamble.database_version.as_str(),preamble.database_creation_date.as_str(),preamble.schema.as_str(),preamble.model.as_str(),preamble.model_creation_date.as_str(),preamble.header_model.as_str(),preamble.header_model_creation_date.as_str(),preamble.user.as_str(),preamble.group.as_str(),preamble.license.as_str(),preamble.options.as_str()]{if value.chars().next().is_some_and(|c|c.is_whitespace()||c=='\u{feff}'){return Err(invalid("invalid EDM metadata field"));}let mut previous=0;for byte in value.bytes(){checkpoint(0)?;if byte==b'\r'||byte==b'\n'||previous==b'*'&&byte==b'/'{return Err(invalid("invalid EDM metadata field"));}previous=byte;}}}
 let header=&snapshot.document.header;
 let strings=|value:Option<&Part21Value>,checkpoint:&mut dyn FnMut(usize)->Result<(),String>|->Result<bool,String>{let Some(Part21Value::List(items))=value else{return Ok(false);};if items.is_empty(){return Ok(false);}for item in items{checkpoint(0)?;if !matches!(item,Part21Value::Str(_)){return Ok(false);}}Ok(true)};
 let description=&header.file_description;if description.len()!=2||!strings(description.first(),checkpoint)?||!matches!(description.get(1),Some(Part21Value::Str(_))){return Err(invalid("invalid FILE_DESCRIPTION attributes"));}
 let name=&header.file_name;if name.len()!=7||![0,1,4,5,6].into_iter().all(|index|matches!(name.get(index),Some(Part21Value::Str(_))))||!strings(name.get(2),checkpoint)?||!strings(name.get(3),checkpoint)?{return Err(invalid("invalid FILE_NAME attributes"));}
 if !matches!(header.file_schema.as_slice(),[Part21Value::List(items)] if matches!(items.as_slice(),[Part21Value::Str(value)] if value=="IFC2X3")){return Err(invalid("FILE_SCHEMA must contain exactly IFC2X3"));}
 let mut ids=HashSet::new();for instance in &snapshot.document.instances{checkpoint(0)?;if instance.id==0||!ids.insert(instance.id){return Err(invalid("instance id must be positive unique u64"));}if instance.entities.is_empty(){return Err(invalid("empty complex instance"));}}
 for instance in &snapshot.document.instances{for(name,args)in &instance.entities{checkpoint(0)?;keyword(name,checkpoint)?;let mut stack=vec![(args.as_slice(),0usize,0usize)];while let Some((items,at,depth))=stack.last_mut(){if *at==items.len(){stack.pop();continue;}let current_depth=*depth;checkpoint(current_depth)?;let value=&items[*at];*at+=1;match value{Part21Value::Ref(id)=>{if !ids.contains(id){return Err(invalid(&format!("instance #{} references missing #{id}",instance.id)));}},Part21Value::List(values)=>{checkpoint(current_depth+1)?;stack.push((values.as_slice(),0,current_depth+1));},Part21Value::Typed{name,items}=>{keyword(name,checkpoint)?;checkpoint(current_depth+1)?;stack.push((items.as_slice(),0,current_depth+1));},Part21Value::Enum(value)=>keyword(value,checkpoint)?,Part21Value::Binary(value)=>{for _ in value.bytes(){checkpoint(current_depth)?;}if !semio_s_artifact_stdio_contract::part21::is_part21_binary(value){return Err(invalid("invalid binary literal"));}},Part21Value::Real(value)=>{if value.coefficient.is_empty()||value.scale>i32::MAX as u32{return Err(invalid("invalid decimal"));}for byte in value.coefficient.bytes(){checkpoint(current_depth)?;if !byte.is_ascii_digit(){return Err(invalid("invalid decimal"));}}},_=>{}}}}}
 Ok(())
}
/// ⚖️ Apply the standalone exchange's finite logical work/depth defaults without constructing text or catalog metadata.
pub fn validate_ifc2x3_exchange(snapshot:&Ifc2x3Snapshot)->Result<(),String>{let mut work=0usize;validate_ifc2x3_exchange_with(snapshot,&mut |depth|{work=work.checked_add(1).ok_or_else(||invalid("work limit"))?;if work>64_000_000{return Err(invalid("work limit"));}if depth>64{return Err(invalid("depth limit"));}Ok(())})}
